

def the_slandered_bride(case, data):
    """F3 — Deut 22:13-21 — ONE LINE slandered_bride_declared writing slander_fine_commanded and unchaste_bride_stoning_commanded (STATUSES) and slanderer_divorce_barred (a BLOCK); the plotting witnesses by CALL (refuge_war_family — 19:15-19), the girl written as a boy by CALL (family — Rebekah's precedent), the courts by CALL (festivals_judges), the stoning rite and the purge formula by CALL (mekoshesh, seducers), the folly by CALL (joseph); Ketubot 4:3 the exam row"""
    del P_[:]
    ask = case['ask']
    if ask == 'when_a_man_takes_a_wife_and_hates_her':
        ink('22:13-14', "'WHEN A MAN TAKES A WIFE and goes in to her AND HATES HER, and lays CHARGES OF WORDS against her and brings out an evil name on her, and says: I took this woman and came near to her and I found not in her the tokens of virginity' — the one 'saying' of the four chapters at 22:17 the father's speech (%s); the wayyiqtol (the narrative verb form) 'and I came near' at 22:14 the man's own account; 22:14 shares %d tokens with 19:16 (the violent witness)" % ([f'{c}:{v}' for c, v in SPAN if 'לאמר' in W(c, v)], TWIN['22:14 vs 19:16']))
        move("the Sifrei 235:1, 236:1-3 (headless — inside the father's words), 237:1-3 (read whole at the reading); cold_run_refuge_war_family (CALL) — RW.the_landmark_and_the_witnesses(as_he_plotted) = %s" % (RW_PLOTTED[1],), "'and lays charges of words' — words, not deeds (237:1); THE CHARGE IS ADULTERY UNDER BETROTHAL BY WITNESSES — 'I did not find in her the tokens' means witnesses that she played the harlot under betrothal (236:1-2 — the reading's find: R. Judah, he is never liable unless he had intercourse); the father opens the pleading first — the plaintiff (236:3); the plotting witnesses' undoing inside the bride's case (19:19's 'as he plotted' by CALL — refuge_war_family)")
        dat("the_charge_of_words a DATA row (the charge adultery under betrothal by witnesses, not the sheet's tokens — 236:1-2; the plotting witnesses refuted in their persons); the exam's person the husband who charges by deeds and not by words — no case of this law")
        return out("when a man takes a wife and hates her (22:13-14) — charges of words, not deeds; the charge adultery under betrothal by witnesses, the father the plaintiff who opens; the plotting witnesses' law inside the bride's case (the Sifrei 235:1-237:3; refuge_war_family's %s by CALL): the husband who charges by deeds outside this law" % (RW_PLOTTED[1][0],), ['accepted'])
    if ask == 'the_girl_written_as_a_boy':
        ink('22:15-16', "'then the father of THE GIRL (written as a boy) and her mother shall take' — the store differs from the DB at ELEVEN verses of chapter 22 and nowhere else, every difference the count of 'the girl' written without its final letter (the reading's store assert: %s the verses); 22:19 alone writes her in full (%s)" % ([15, 16, 20, 21, 23, 24, 25, 26, 27, 28, 29], [v for v in range(1, 30) if 'הנערה' in W22(v)]))
        move("the Sifrei 238:1 (read whole at the reading); cold_run_family (CALL) — FA.commission(naar_ketiv) = %s (Rebekah written 'na'ar' — a boy — five times and 'na'arah' — a girl — never)" % (FA_NAAR[0],), "'the father of the girl' — the girl written as a boy (the ketiv layer, the masculine consonants) and read as a girl: the precedent Genesis 24's Rebekah, five times a boy in the writing and never a girl (family's (5, 0) by CALL); the twelve seats of chapter 22 the reading measured (22:15, 16, 19, 20, 21, 23, 24, 25, 26, 27, 28, 29) — 22:19's fine alone in the full form")
        dat("the_girls_written_form a DATA row (the twelve seats — eleven written as a boy, 22:19 in full; Rebekah's five the precedent by CALL); the exam's person the reader who reads the boy's consonants as a boy — the read form the girl's, the writing the store's")
        return out("the girl written as a boy (22:15-16) — eleven seats of chapter 22 without the final letter, 22:19 alone in full; Rebekah's five the precedent (family's %s by CALL): the store carries the written form beside the read" % (FA_NAAR[0],), ['accepted'])
    if ask == 'the_father_and_the_mother_and_the_elders':
        ink('22:15-18', "'the father of the girl and her mother shall take and bring out the tokens of the girl's virginity to THE ELDERS OF THE CITY AT THE GATE … and THEY SHALL SPREAD THE GARMENT before the elders of the city; and the elders of that city shall take the man AND CHASTISE HIM' — 'and chastise him' at %s (21:18's rebellious son the twin); the elders of the city at 22:15, 22:17, 22:18 (Onkelos 'the elders of the city' at %s)" % (P('ויסרו', 'אתו', books=None), [(21, 3), (21, 4), (21, 6), (22, 15), (22, 17), (22, 18)]))
        move("the Sifrei 238:1-6, 239:1 (read whole at the reading); cold_run_festivals_judges (CALL) — FJ.the_judges_in_every_gate(the_three_tiers) called (found %s)" % (FOUND(FJ_TIERS[0]),), "'the father and the mother' — they bring the witnesses who refute the husband's witnesses (238:1-2); 'the elders of the city at the gate' — the court of the city, the gate the bench (festivals_judges' three tiers by CALL — 16:18's courts in every gate); 'and they shall spread the garment' — they make the matter as clear as a garment: the figure, not a cloth (238:5 — the_spreading_of_the_garment); 'and chastise him' — lashes (239:1)")
        dat("the_spreading_of_the_garment a DATA row (the figure — the matter made clear as a garment, 238:5); the_case_court a DATA row (the elders of the city at the gate — 16:18's tier by CALL); the exam's person the father who brings a cloth and no witnesses — the figure, not the cloth")
        return out("the father and the mother and the elders (22:15-18) — the parents bring the refuting witnesses; the elders at the gate the court; the garment spread a figure — the matter made clear; the chastising lashes (the Sifrei 238:1-239:1; festivals_judges by CALL): the father with a cloth and no witnesses brings nothing", ['accepted'])
    if ask == 'the_hundred_of_silver':
        ink('22:19', "'AND FINE HIM A HUNDRED OF SILVER and give it to the father of the girl, because he brought out an evil name on a virgin of Israel; and to him she shall be as a wife, HE MAY NOT SEND HER AWAY ALL HIS DAYS' — the parser %s at 22:19; 'a virgin of Israel' at %s; 22:19 shares %d tokens with 22:29 (the rapist's twin — 'to him she shall be as a wife', 'he may not send her away all his days'); 'send her away' WITH the lamed here and without it at 22:29 (%s)" % (PARSE[(22, 19)][0], P('בתולת', 'ישראל', books=None), TWIN['22:19 vs 22:29'], [(c, v, x) for c, v in SPAN for x in W(c, v) if x in ('לשלחה', 'שלחה')]))
        move("the Sifrei 239:1-5 (read whole at the reading); Onkelos 22:19 'a hundred sela'; MISHNAH KETUBOT 4:3 (the exam row, read whole)", "'a hundred of silver' — a hundred SELA (Onkelos — the coin the answer sheet fixes); 'and give it to the father of the girl' — the convert's daughter: converted with her mother and born in sanctity — she has the hundred and the door of her father's house; conceived in sanctity and born in sanctity — she has both; conceived and born outside — neither (Ketubot 4:3 — the exam row: the door of her father's house a commandment, not a bar); 'to him she shall be as a wife' — even ugly, even a woman he hates (239:4); 'he may not send her away all his days' — the lamed on the sending (the reading's find — the two forms of one clause at 22:19 and 22:29)")
        dat("THE WRITES slander_fine_commanded (a STATUS) and slanderer_divorce_barred (a BLOCK) on israel_people at the chapters' own day (DK2); THE PARAMETER the_hundred (a hundred sela by Onkelos; Ketubot 4:3's convert's daughter the sheet's case); the exam's person the slanderer of a convert's daughter born outside sanctity — no hundred, no door")
        return out("the hundred of silver (22:19) — a hundred sela to the father; the convert's daughter born in sanctity has it, born outside neither the hundred nor the door; to him a wife even ugly, never sent away — the lamed's form (the Sifrei 239:1-5; Onkelos; Mishnah Ketubot 4:3): THE WRITES slander_fine_commanded and slanderer_divorce_barred on Israel at the chapters' own day; the slanderer of the convert's daughter born outside owes no hundred", ['slander_fine_commanded', 'slanderer_divorce_barred'])
    if ask == 'if_the_thing_was_true':
        ink('22:20-21', "'But IF THIS THING WAS TRUE, the tokens were not found for the girl: they shall bring out the girl to the door of her father's house and THE MEN OF HER CITY SHALL STONE HER WITH STONES AND SHE SHALL DIE, for she did A FOLLY IN ISRAEL to play the harlot in her father's house; AND YOU SHALL PURGE THE EVIL FROM YOUR MIDST' — 'folly in Israel' at %s (Genesis 34:7 the first); the stoning root at %s; the purge formula's seats %s (22:21 the SIXTH); 22:21 shares %d tokens with 21:21 (the rebellious son's stoning) and %d with Genesis 34:7" % (P('נבלה', 'בישראל', books=None), [(c, v) for c, v in SPAN for x in W(c, v) if 'סקל' in x], P('ובערת', 'הרע', 'מקרבך', books=T), TWIN['22:21 vs 21:21'], TWIN['22:21 vs Gen 34:7']))
        move("the Sifrei 240:1-6, 241:1-4 (read whole at the reading); cold_run_mekoshesh (CALL) — MK.capital_procedure(stoning, died_at) = %s; cold_run_seducers (CALL) — SE.the_inciter(the_hand_first) = %s, SE.the_readback(the_purge_formulas_nine_seats) = %s; cold_run_joseph (CALL) — JO.dinah(outrage_phrase) = %s" % (MK_STONING[1], SE_HAND[1], SE_NINE[1], JO_FOLLY[0]), "'the tokens were not found' — by witnesses, that she committed adultery under betrothal (240:2); 'to the door of her father's house' — see the growth you have raised (240:4); 'the men of her city shall stone her' — the stoning rite, the witnesses' hand first (mekoshesh's rite and seducers' hand by CALL); 'a folly in Israel' — Genesis 34:7's phrase, the tape's own line outraged (joseph's 'not_done_in_israel' by CALL); 'to play the harlot in her father's house' — the father's house the place of the sin, not the stoning (241:2); 'and you shall purge the evil' — THE PURGE FORMULA'S SIXTH SEAT of nine (seducers' nine by CALL; evil_purged_from_the_midst the case's body effect, ZERO persons on the tape — SCANS %s)" % (SCANS['evil_purged_from_the_midst'],))
        dat("THE WRITE unchaste_bride_stoning_commanded — a STATUS on israel_people at the chapters' own day (DK2); the bride's own verdict stoned with the evil purged (the body effects reused — the answer sheet's person, no bride on the tape); the exam's person the bride whose adultery under betrothal is proved by witnesses — stoned at her father's door")
        return out("if the thing was true (22:20-21) — witnesses to adultery under betrothal; the girl at her father's door, the men of her city stoning her, the witnesses' hand first; folly in Israel Dinah's phrase; the purge formula's sixth seat of nine (the Sifrei 240:1-241:4; mekoshesh's %s, seducers' %s and joseph's %s by CALL): THE WRITE unchaste_bride_stoning_commanded, a STATUS on Israel at the chapters' own day; the proved bride stoned and the evil purged" % (MK_STONING[1][0], SE_HAND[1][0], JO_FOLLY[0]), ['unchaste_bride_stoning_commanded', 'stoned', 'evil_purged_from_the_midst'])
    return 'no verdict in span', [], list(P_)


def the_adulterer_the_betrothed_girl_and_the_seducer(case, data):
    """F4 — Deut 22:22-29 — ONE LINE adultery_betrothed_seducer_declared writing adulterers_death_commanded, betrothed_girl_city_field_declared and rapist_fifty_commanded (STATUSES) and rapist_divorce_barred (a BLOCK); Leviticus 20:10's adulterers and the strangled by CALL (sanctions), Exodus 22:15-16's seducer by CALL (mishpatim_2 — the fifty a POINTER there), the bride-price and the folly by CALL (joseph), Hagar's word by CALL (primeval), the purge formula by CALL (seducers); Sanhedrin 11:1, Ketubot 3:1, 3:5 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'a_man_found_lying_with_a_married_woman':
        ink('22:22', "'When a man is found lying with a woman MARRIED TO A HUSBAND, THEY SHALL BOTH DIE, the man who lay with the woman and the woman; and you shall purge the evil FROM ISRAEL' — 'married to a husband' at %s (Sarah's phrase, Genesis 20:3 — the tape's came_in_a_dream); the parser %s at 22:22 ('the two of them' starred); the purge formula's second form 'from Israel' at %s (22:22 the SEVENTH seat); 22:22 shares %d tokens with Leviticus 20:10 and %d with Genesis 20:3" % (P('בעלת', 'בעל', books=T), PARSE[(22, 22)][0], P('ובערת', 'הרע', 'מישראל', books=T), TWIN['22:22 vs Lev 20:10'], TWIN['22:22 vs Gen 20:3']))
        move("the Sifrei 242:1-6 (read whole at the reading); MISHNAH SANHEDRIN 11:1 (the exam row, read whole); cold_run_sanctions (CALL) — SA.census(strangled) = %s, SA.grade(married_woman) = %s" % (SA_STRANGLED[0], SA_MW[0]), "'married to a husband' — Sarah's phrase at Genesis 20:3, the tape's own line the readback's REFERENCE; 'they shall both die' — the bare death filled as STRANGLING: 'these are the strangled — … the man's wife's paramour' (Sanhedrin 11:1 — the Leviticus cell's census by CALL: Leviticus 20:10's bare 'put to death'); 'the two of them' — the two alike, not the one who is a minor (242:4 — the adulterers' ages a parameter); 'from Israel' — the formula's second form (242:6); the karet class takes no marriage — neither release nor levirate (sanctions' grade by CALL)")
        dat("THE WRITE adulterers_death_commanded — a STATUS on israel_people at the chapters' own day (DK2); THE PARAMETER the_adulterers_ages (the two alike, the minor excluded — 242:4); the adulterers' own verdict put_to_death (the body effect reused — SCANS %s, seven persons on the tape); the exam's person the paramour of a married woman found by witnesses — strangled with her" % (len(SCANS['put_to_death'] or []),))
        return out("a man found lying with a married woman (22:22) — Sarah's phrase; both die by strangling, Leviticus 20:10's bare death filled; the two alike, not the minor; the purge from Israel — the seventh seat (the Sifrei 242:1-6; Mishnah Sanhedrin 11:1; sanctions' %s by CALL): THE WRITE adulterers_death_commanded, a STATUS on Israel at the chapters' own day; the paramour strangled with her" % (SA_STRANGLED[0][0],), ['adulterers_death_commanded', 'put_to_death'])
    if ask == 'the_betrothed_girl_in_the_city_and_in_the_field':
        ink('22:23-27', "'When A GIRL, A VIRGIN, IS BETROTHED to a man, and a man finds her IN THE CITY and lies with her, you shall bring them both out to the gate of that city and stone them with stones and they shall die — the girl because she cried not in the city, and the man because he HUMBLED his neighbor's wife … But if the man finds the betrothed girl IN THE FIELD and the man seizes her and lies with her, the man alone who lay with her shall die' — the parser %s at 22:24; 'humbled' at %s; 22:24 shares %d tokens with 17:5 (the idolater's stoning at the gate); the purge formula's EIGHTH seat (22:24)" % (PARSE[(22, 24)][0], [(c, v) for c, v in SPAN for x in W(c, v) if x in ('ענה', 'עניתה', 'וענה')], TWIN['22:24 vs 17:5']))
        move("the Sifrei 243:1-6, 244:1-4 (read whole at the reading); cold_run_primeval (CALL) — PV.hagar(affliction_reading) = %s; cold_run_mekoshesh (CALL) — the stoning rite; cold_run_seducers (CALL) — the purge's eighth seat" % (PV_HAGAR[0],), "'a girl, a virgin, betrothed' — three conditions: a girl and not a grown woman, a virgin and not one lain with, betrothed and not married (243:1); 'in the city' she is stoned for not crying out, 'in the field' he alone — THE CITY AND THE FIELD TWO ARMS OF ONE PREDICATE, the presumption of rescue: in the city one would have saved her had she cried; in the field she cried and there was none to save (243:2, 244:2-4); 'he humbled' — Hagar's word (Genesis 16:6 — primeval's 'not_obliged_for_her_good_or_ill' by CALL); 'he shall die alone' — the girl no sin worthy of death, Onkelos 'no liability of a death sentence' (22:26 — 22:19's Aramaic clause its twin)")
        dat("THE WRITE betrothed_girl_city_field_declared — a STATUS on israel_people at the chapters' own day (DK2); the_city_and_the_field a DATA row (the presumption of rescue — two arms of one predicate); the betrothed girl's and her man's verdict stoned (the body effect reused); the exam's person the betrothed girl seized in the field who cried — exempt, the man alone stoned")
        return out("the betrothed girl in the city and in the field (22:23-27) — three conditions: a girl, a virgin, betrothed; in the city both stoned, she for not crying; in the field he alone, she cried and none saved — the presumption of rescue's two arms; humbled Hagar's word (the Sifrei 243:1-244:4; primeval's %s by CALL): THE WRITE betrothed_girl_city_field_declared, a STATUS on Israel at the chapters' own day; the girl seized in the field exempt, her man stoned" % (PV_HAGAR[0],), ['betrothed_girl_city_field_declared', 'stoned'])
    if ask == 'the_pursuers_law':
        ink('22:26', "'to the girl you shall do nothing, the girl has no sin worthy of death, for AS WHEN A MAN RISES AGAINST HIS NEIGHBOR AND MURDERS HIM, so is this matter' — the murderer's clause inside the girl's exemption; 'a soul' (nefesh) the murder's object")
        move("the Sifrei 243:2, 244:1 (read whole at the reading — THE PURSUER'S LAW, the reading's find); MIDDOT.md I1 (a fortiori)", "'as when a man rises against his neighbor and murders him' — this comes to teach and is found taught: as the betrothed girl may be saved by the pursuer's life, so the pursued victim of a murderer may be saved by the pursuer's life (243:2 — the pursuer's law read off the comparison, both ways); the rapist and the seducer by three a fortiori arguments — the girl exempt a fortiori from the field's case (244:1 — I1 checked in MIDDOT.md)")
        dat("the_pursuers_law a DATA row (the comparison read both ways — the betrothed girl and the pursued victim each saved by the pursuer's life; 243:2); the_three_a_fortiori a DATA row (244:1 — I1); the exam's person who kills the pursuer to save the betrothed girl — accepted, the pursuer's life the price")
        return out("the pursuer's law (22:26) — the comparison that comes to teach and is taught: the betrothed girl and the pursued victim each saved by the pursuer's life; the rapist and the seducer by three a fortiori arguments (the Sifrei 243:2, 244:1; I1): the rescuer who kills the pursuer accepted", ['accepted'])
    if ask == 'the_seducer_of_the_unbetrothed':
        ink('22:28', "'When a man finds A GIRL, A VIRGIN, WHO IS NOT BETROTHED, and seizes her and lies with her, and they are found' — Exodus 22:15's seducer by name: 22:28 shares %d tokens with Exodus 22:15 (%s the shared run); the closest kin %s" % (TWIN['22:28 vs Exod 22:15'], SHARED(DV(22, 28), ('Exod', 22, 15)), KINC[(22, 28)][0]))
        move("the Sifrei 245:1-4 (read whole at the reading); cold_run_mishpatim_2 (CALL) — the PROBES row %s read; cold_run_joseph (CALL) — JO.dinah(mohar_by_call) = %s, JO.dinah(seducer_sheet) = %s" % (('fifty', 2572, 'Deut', 22, 29), JO_MOHAR[0], JO_SHEET[0]), "'a girl, a virgin, not betrothed' — the same three conditions with the betrothal denied (245:1); 'and seizes her' — the rapist, against Exodus 22:15's seducer who entices (245:2); 'and they are found' — by witnesses (245:3); THE EXODUS RUNNER READ THIS VERSE AT ITS COMPILE — its fine a POINTER ('FETCH-50') to 22:29's constant, the PROBES row ('fifty', 2572, 'Deut', 22, 29) on file; the seducer gives three things and the rapist four — humiliation, degradation, the fine, and the rapist's pain (Ketubot 3:4 — joseph's ('three', 'four') by CALL, Shechem's case the tape's own)")
        dat("the_seducer_and_the_rapist a DATA row (the seducer entices, the rapist seizes; three things and four — Ketubot 3:4 by CALL); the exam's person the seducer who entices the unbetrothed girl — Exodus 22:15's case, this verse the rapist's")
        return out("the seducer of the unbetrothed (22:28) — the three conditions with the betrothal denied; seizes, not entices; found by witnesses; Exodus 22:15's cell read this verse forward, its fine a pointer here; three things and four (the Sifrei 245:1-4; mishpatim_2's PROBES row and joseph's %s by CALL): the enticer Exodus's case, the seizer this verse's" % (JO_SHEET[0],), ['accepted'])
    if ask == 'the_fifty':
        ink('22:29', "'the man who lay with her shall give to the girl's father FIFTY OF SILVER, and to him she shall be as a wife because he humbled her, HE MAY NOT SEND HER AWAY ALL HIS DAYS' — the parser %s at 22:29; 22:29 shares %d token with Exodus 22:16 (the pointer's seat: 'like the dowry of the virgins'); 'send her away' WITHOUT the lamed (%s at 22:29)" % (PARSE[(22, 29)][0], TWIN['22:29 vs Exod 22:16'], [x for x in W22(29) if x == 'שלחה']))
        move("the Sifrei 245:5-7 (read whole at the reading); Onkelos 22:29 'fifty sela'; MISHNAH KETUBOT 3:5 (the exam row, read whole); cold_run_joseph (CALL) — the FETCH-50 %s" % (JO_MOHAR[0],), "'fifty of silver' — fifty sela (Onkelos) — THE CONSTANT the Exodus pointer fetches: Exodus 22:16's 'like the dowry of the virgins' holds no number, this verse holds the fifty (Ketubot 29b by the Exodus cell's own why); 'to him she shall be as a wife' — a wife fit for him: the rapist drinks from his vessel even lame or blind; but a matter of licentiousness found in her, or she unfit to enter Israel — he may not keep her, 'to him she shall be as a wife' — a wife fit for him (Ketubot 3:5 — the exam row); 'he may not send her away' — without the lamed, the slanderer's clause's twin form (245:7)")
        dat("THE WRITES rapist_fifty_commanded (a STATUS — THE PARAMETER the_fifty, fifty sela by Onkelos, the Exodus pointer's constant) and rapist_divorce_barred (a BLOCK) on israel_people at the chapters' own day (DK2); the_rapists_wife a DATA row with the exit (Ketubot 3:5 — the unfit and the licentious); the exam's person the rapist of a girl unfit to enter Israel — pays the fifty and may not keep her")
        return out("the fifty (22:29) — fifty sela to the father, the constant Exodus 22:16's pointer fetches; to him a wife fit for him — he drinks from his vessel even lame or blind, the unfit and the licentious excepted; never sent away, the clause without the lamed (the Sifrei 245:5-7; Onkelos; Mishnah Ketubot 3:5; joseph's %s by CALL): THE WRITES rapist_fifty_commanded and rapist_divorce_barred on Israel at the chapters' own day; the rapist of the unfit pays and may not keep her" % (JO_MOHAR[0][0],), ['rapist_fifty_commanded', 'rapist_divorce_barred'])
    if ask == 'the_fines_girls':
        ink('22:28-29', "'a girl, a virgin' — which girls have a fine and which not: the answer sheet's parameter on the ink's 'virgin' (Ketubot 3:1 the exam row); the karet-grade unions without a court death (Leviticus 18's list by the Leviticus cell)")
        move("MISHNAH KETUBOT 3:1 (the exam row, read whole); cold_run_sanctions (CALL) — SA.census(lashes) = %d names (the karet-grade unions without a court death)" % (len(SA_LASHES[0]),), "these girls have a fine: one who comes upon a mamzeret, a Gibeonite, a Samaritan; upon a convert, a captive, a maidservant redeemed, converted or freed under three years and a day; upon his sister, his father's sister, his mother's sister, his wife's sister, his brother's wife, his father's brother's wife, the menstruant — a fine, though they are under karet (excision), for there is no court death for them (Ketubot 3:1 — the exam row); the Leviticus cell's lash list the same class: the unions with karet and no court death (sanctions' census by CALL — 'the lash itself is Deut 25:2-3's [IMPORT]')")
        dat("THE PARAMETER the_fines_girls (Ketubot 3:1 — the list, the karet-without-death class; sanctions' lash list the Leviticus twin by CALL); the exam's person the rapist of his father's sister — the fine paid though the union is under karet")
        return out("the fines' girls (22:28-29) — the mamzeret, the Gibeonite, the Samaritan, the convert and the captive under three years, the sister and the aunts, the menstruant: a fine though under karet, no court death (Mishnah Ketubot 3:1; sanctions' %d-name lash list by CALL): the rapist of his father's sister pays the fine" % (len(SA_LASHES[0]),), ['accepted'])
    return 'no verdict in span', [], list(P_)
